#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include "kernel.h"
#include <string>

static void check_fp32_contiguous_cuda(
    const torch::Tensor& tensor, const std::string& name) {
    TORCH_CHECK(tensor.is_cuda(), name, " must be a CUDA tensor");
    TORCH_CHECK(
        tensor.dtype() == torch::kFloat32,
        name, " must have float32 dtype, got ", tensor.dtype());
    TORCH_CHECK(tensor.is_contiguous(), name, " must be contiguous");
}

// Destination-passing-style entry. Per definition.json:
//   grad_q_embed : [batch_size, num_heads,    seq_len, head_dim=128] fp32
//   grad_k_embed : [batch_size, num_kv_heads, seq_len, head_dim]      fp32
//   q            : [batch_size, num_heads,    seq_len, head_dim]      fp32
//   k            : [batch_size, num_kv_heads, seq_len, head_dim]      fp32
//   cos          : [batch_size, seq_len, head_dim]                    fp32
//   sin          : [batch_size, seq_len, head_dim]                    fp32
//   grad_q       : same shape as q  (DPS)
//   grad_k       : same shape as k  (DPS)
//   grad_cos     : [batch_size, seq_len, head_dim]                    fp32 (DPS)
//   grad_sin     : [batch_size, seq_len, head_dim]                    fp32 (DPS)
//
// head_dim = 128 is pinned. num_heads, num_kv_heads, seq_len, and
// batch_size are workload-variable. The kernel set runs three
// launches on the current PyTorch CUDA stream:
//   1. problem_068_grad_x_launcher(grad_q_embed, cos, sin, grad_q)
//   2. problem_068_grad_x_launcher(grad_k_embed, cos, sin, grad_k)
//   3. problem_068_grad_cos_sin_launcher(grad_q_embed, grad_k_embed,
//      q, k, grad_cos, grad_sin)
// Kernels 1 and 2 share the same per-element template (head axis is
// determined by the input tensor's size(1)). Kernel 3 reduces over
// both H and H_kv inside a single CTA per (b, s).
void run(
    const torch::Tensor& grad_q_embed,
    const torch::Tensor& grad_k_embed,
    const torch::Tensor& q,
    const torch::Tensor& k,
    const torch::Tensor& cos,
    const torch::Tensor& sin,
    torch::Tensor grad_q,
    torch::Tensor grad_k,
    torch::Tensor grad_cos,
    torch::Tensor grad_sin
) {
    TORCH_CHECK(grad_q_embed.dim() == 4,
                "grad_q_embed must be 4D [B, H, S, D]");
    TORCH_CHECK(grad_k_embed.dim() == 4,
                "grad_k_embed must be 4D [B, H_kv, S, D]");
    TORCH_CHECK(q.dim() == 4, "q must be 4D");
    TORCH_CHECK(k.dim() == 4, "k must be 4D");
    TORCH_CHECK(cos.dim() == 3, "cos must be 3D [B, S, D]");
    TORCH_CHECK(sin.dim() == 3, "sin must be 3D [B, S, D]");
    TORCH_CHECK(grad_q.dim() == 4, "grad_q must be 4D");
    TORCH_CHECK(grad_k.dim() == 4, "grad_k must be 4D");
    TORCH_CHECK(grad_cos.dim() == 3, "grad_cos must be 3D");
    TORCH_CHECK(grad_sin.dim() == 3, "grad_sin must be 3D");

    constexpr int64_t kHeadDim = 128;
    TORCH_CHECK(grad_q_embed.size(3) == kHeadDim,
                "head_dim must be 128 for problem_068, got ",
                grad_q_embed.size(3));
    TORCH_CHECK(grad_k_embed.size(3) == kHeadDim,
                "grad_k_embed head_dim must be 128");
    TORCH_CHECK(q.sizes() == grad_q_embed.sizes(),
                "q shape must match grad_q_embed");
    TORCH_CHECK(k.sizes() == grad_k_embed.sizes(),
                "k shape must match grad_k_embed");
    TORCH_CHECK(grad_q.sizes() == grad_q_embed.sizes(),
                "grad_q shape must match grad_q_embed");
    TORCH_CHECK(grad_k.sizes() == grad_k_embed.sizes(),
                "grad_k shape must match grad_k_embed");
    TORCH_CHECK(cos.size(2) == kHeadDim && sin.size(2) == kHeadDim,
                "cos/sin last dim must be head_dim=128");
    TORCH_CHECK(cos.size(0) == grad_q_embed.size(0) &&
                cos.size(1) == grad_q_embed.size(2),
                "cos must have shape [B, S, D] matching grad_q_embed");
    TORCH_CHECK(sin.size(0) == grad_q_embed.size(0) &&
                sin.size(1) == grad_q_embed.size(2),
                "sin must have shape [B, S, D] matching grad_q_embed");
    TORCH_CHECK(grad_cos.sizes() == cos.sizes(),
                "grad_cos shape must match cos");
    TORCH_CHECK(grad_sin.sizes() == sin.sizes(),
                "grad_sin shape must match sin");
    TORCH_CHECK(grad_q_embed.size(0) == grad_k_embed.size(0) &&
                grad_q_embed.size(2) == grad_k_embed.size(2),
                "Q and K must agree on batch_size and seq_len");

    check_fp32_contiguous_cuda(grad_q_embed, "grad_q_embed");
    check_fp32_contiguous_cuda(grad_k_embed, "grad_k_embed");
    check_fp32_contiguous_cuda(q, "q");
    check_fp32_contiguous_cuda(k, "k");
    check_fp32_contiguous_cuda(cos, "cos");
    check_fp32_contiguous_cuda(sin, "sin");
    check_fp32_contiguous_cuda(grad_q, "grad_q");
    check_fp32_contiguous_cuda(grad_k, "grad_k");
    check_fp32_contiguous_cuda(grad_cos, "grad_cos");
    check_fp32_contiguous_cuda(grad_sin, "grad_sin");

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    problem_068_grad_x_launcher(grad_q_embed, cos, sin, grad_q, stream);
    problem_068_grad_x_launcher(grad_k_embed, cos, sin, grad_k, stream);
    problem_068_grad_cos_sin_launcher(
        grad_q_embed, grad_k_embed, q, k, grad_cos, grad_sin, stream);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def(
        "run", &run,
        "fp32 fused RoPE-application backward: grad_q / grad_k via "
        "per-element rotate-half-with-cos/sin (two launches sharing "
        "one launcher); grad_cos / grad_sin via per-(b, s) reduction "
        "over both H and H_kv (one launch). head_dim=128 pinned.");
}

#include "kernel.h"
#include <cuda_runtime.h>

// fp32 fused RoPE application backward.
//
// Kernel A computes grad_x = grad_x_embed * cos - rotate_half(grad_x_embed)
// * sin per element. Grid: (seq_len, num_heads_axis, batch_size).
// BLOCK_THREADS = head_dim = 128.
//
// Kernel B computes grad_cos[b, s, d] and grad_sin[b, s, d] as the
// per-head sum of (grad_q_embed * q) and (grad_q_embed * rotate_half(q))
// plus the same K-side contributions. Grid: (seq_len, batch_size).
// BLOCK_THREADS = head_dim = 128. Each thread holds two fp32
// accumulators and iterates over the head axis in a stride-loop.

namespace {

constexpr int kHeadDim = 128;
constexpr int kHalfHeadDim = 64;
constexpr int kBlockThreads = kHeadDim;

__device__ inline void resolve_partner(
    int d, int& partner_d, float& partner_sign) {
    if (d < kHalfHeadDim) {
        partner_d = d + kHalfHeadDim;
        partner_sign = -1.0f;
    } else {
        partner_d = d - kHalfHeadDim;
        partner_sign = 1.0f;
    }
}

__global__ void __launch_bounds__(kBlockThreads, 8)
problem_068_grad_x_kernel(
    const float* __restrict__ grad_x_embed,
    const float* __restrict__ cos_table,
    const float* __restrict__ sin_table,
    float* __restrict__ grad_x,
    int num_heads_axis,
    int seq_len) {

    const int s = blockIdx.x;
    const int h = blockIdx.y;
    const int b = blockIdx.z;
    const int d = threadIdx.x;

    int partner_d;
    float partner_sign;
    resolve_partner(d, partner_d, partner_sign);

    const int row_offset =
        ((b * num_heads_axis + h) * seq_len + s) * kHeadDim;
    const int cs_offset = (b * seq_len + s) * kHeadDim;

    const float g       = grad_x_embed[row_offset + d];
    const float g_partner = grad_x_embed[row_offset + partner_d];
    const float cs      = cos_table[cs_offset + d];
    const float sn      = sin_table[cs_offset + d];

    // grad_x = grad_output * cos - rotate_half(grad_output) * sin
    //        = g * cs - (partner_sign * g_partner) * sn
    grad_x[row_offset + d] = g * cs - partner_sign * g_partner * sn;
}

__global__ void __launch_bounds__(kBlockThreads, 4)
problem_068_grad_cos_sin_kernel(
    const float* __restrict__ grad_q_embed,
    const float* __restrict__ grad_k_embed,
    const float* __restrict__ q,
    const float* __restrict__ k,
    float* __restrict__ grad_cos,
    float* __restrict__ grad_sin,
    int num_heads,
    int num_kv_heads,
    int seq_len) {

    const int s = blockIdx.x;
    const int b = blockIdx.y;
    const int d = threadIdx.x;

    int partner_d;
    float partner_sign;
    resolve_partner(d, partner_d, partner_sign);

    float acc_cos = 0.0f;
    float acc_sin = 0.0f;

    // Q-side reduction over num_heads heads.
    for (int h = 0; h < num_heads; ++h) {
        const int row_offset =
            ((b * num_heads + h) * seq_len + s) * kHeadDim;
        const float g     = grad_q_embed[row_offset + d];
        const float x_v   = q[row_offset + d];
        const float x_par = q[row_offset + partner_d];
        const float rh    = partner_sign * x_par;
        acc_cos += g * x_v;
        acc_sin += g * rh;
    }

    // K-side reduction over num_kv_heads heads.
    for (int h = 0; h < num_kv_heads; ++h) {
        const int row_offset =
            ((b * num_kv_heads + h) * seq_len + s) * kHeadDim;
        const float g     = grad_k_embed[row_offset + d];
        const float x_v   = k[row_offset + d];
        const float x_par = k[row_offset + partner_d];
        const float rh    = partner_sign * x_par;
        acc_cos += g * x_v;
        acc_sin += g * rh;
    }

    const int cs_offset = (b * seq_len + s) * kHeadDim;
    grad_cos[cs_offset + d] = acc_cos;
    grad_sin[cs_offset + d] = acc_sin;
}

}  // namespace

void problem_068_grad_x_launcher(
    const torch::Tensor& grad_x_embed,
    const torch::Tensor& cos_table,
    const torch::Tensor& sin_table,
    torch::Tensor& grad_x,
    cudaStream_t stream) {

    const int batch_size = static_cast<int>(grad_x_embed.size(0));
    const int num_heads_axis = static_cast<int>(grad_x_embed.size(1));
    const int seq_len = static_cast<int>(grad_x_embed.size(2));

    dim3 grid(seq_len, num_heads_axis, batch_size);
    dim3 block(kBlockThreads);

    problem_068_grad_x_kernel<<<grid, block, 0, stream>>>(
        grad_x_embed.data_ptr<float>(),
        cos_table.data_ptr<float>(),
        sin_table.data_ptr<float>(),
        grad_x.data_ptr<float>(),
        num_heads_axis,
        seq_len);
}

void problem_068_grad_cos_sin_launcher(
    const torch::Tensor& grad_q_embed,
    const torch::Tensor& grad_k_embed,
    const torch::Tensor& q,
    const torch::Tensor& k,
    torch::Tensor& grad_cos,
    torch::Tensor& grad_sin,
    cudaStream_t stream) {

    const int batch_size = static_cast<int>(grad_q_embed.size(0));
    const int num_heads = static_cast<int>(grad_q_embed.size(1));
    const int num_kv_heads = static_cast<int>(grad_k_embed.size(1));
    const int seq_len = static_cast<int>(grad_q_embed.size(2));

    dim3 grid(seq_len, batch_size);
    dim3 block(kBlockThreads);

    problem_068_grad_cos_sin_kernel<<<grid, block, 0, stream>>>(
        grad_q_embed.data_ptr<float>(),
        grad_k_embed.data_ptr<float>(),
        q.data_ptr<float>(),
        k.data_ptr<float>(),
        grad_cos.data_ptr<float>(),
        grad_sin.data_ptr<float>(),
        num_heads,
        num_kv_heads,
        seq_len);
}

#pragma once

#ifndef PROBLEM_068_FUSED_ROPE_BACKWARD_KERNEL_H
#define PROBLEM_068_FUSED_ROPE_BACKWARD_KERNEL_H

#include <cuda_runtime.h>
#include <torch/extension.h>

// Host launcher set for the fp32 fused RoPE-application backward
// kernel. The reference forward is:
//   output[..., d] = x[..., d] * cos[..., d] +
//                    rotate_half(x)[..., d] * sin[..., d]
// where rotate_half(x)[d] = -x[d + 64] for d in [0, 64)
//                        =  x[d - 64] for d in [64, 128)
//
// Backward gradients (per the definition):
//   grad_x   = grad_output * cos - rotate_half(grad_output) * sin
//   grad_cos = sum_h(grad_q_embed * q) + sum_h_kv(grad_k_embed * k)
//   grad_sin = sum_h(grad_q_embed * rotate_half(q)) +
//              sum_h_kv(grad_k_embed * rotate_half(k))
//
// head_dim = 128 and half_head_dim = 64 are pinned. The DPS entry
// launches two kernels in sequence:
//   * `problem_068_grad_x_launcher` is invoked TWICE — once for
//     (grad_q_embed, grad_q) using num_heads, once for
//     (grad_k_embed, grad_k) using num_kv_heads.
//   * `problem_068_grad_cos_sin_launcher` is invoked ONCE; it
//     accumulates the per-(b, s, d) reduction over BOTH H and
//     H_kv axes in a single CTA.
void problem_068_grad_x_launcher(
    const torch::Tensor& grad_x_embed,
    const torch::Tensor& cos_table,
    const torch::Tensor& sin_table,
    torch::Tensor& grad_x,
    cudaStream_t stream);

void problem_068_grad_cos_sin_launcher(
    const torch::Tensor& grad_q_embed,
    const torch::Tensor& grad_k_embed,
    const torch::Tensor& q,
    const torch::Tensor& k,
    torch::Tensor& grad_cos,
    torch::Tensor& grad_sin,
    cudaStream_t stream);

#endif  // PROBLEM_068_FUSED_ROPE_BACKWARD_KERNEL_H
